

import datetime as dt
import typing

import pydantic
import typing_extensions
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from ..core.serialization import FieldMetadata
from .dataset_event_classifications_value_item import DatasetEventClassificationsValueItem
from .dataset_event_metadata import DatasetEventMetadata
from .object_reference_nullish import ObjectReferenceNullish


class DatasetEvent(UniversalBaseModel):
    id: str = pydantic.Field()
    """
    A unique identifier for the dataset event. If you don't provide one, Braintrust will generate one for you
    """

    xact_id: typing_extensions.Annotated[
        str,
        FieldMetadata(alias="_xact_id"),
        pydantic.Field(
            alias="_xact_id",
            description="The transaction id of an event is unique to the network operation that processed the event insertion. Transaction ids are monotonically increasing over time and can be used to retrieve a versioned snapshot of the dataset (see the `version` parameter)",
        ),
    ]
    """
    The transaction id of an event is unique to the network operation that processed the event insertion. Transaction ids are monotonically increasing over time and can be used to retrieve a versioned snapshot of the dataset (see the `version` parameter)
    """

    created: dt.datetime = pydantic.Field()
    """
    The timestamp the dataset event was created
    """

    pagination_key: typing_extensions.Annotated[
        typing.Optional[str],
        FieldMetadata(alias="_pagination_key"),
        pydantic.Field(
            alias="_pagination_key",
            description="A stable, time-ordered key that can be used to paginate over dataset events. This field is auto-generated by Braintrust and only exists in Brainstore.",
        ),
    ] = None
    """
    A stable, time-ordered key that can be used to paginate over dataset events. This field is auto-generated by Braintrust and only exists in Brainstore.
    """

    project_id: str = pydantic.Field()
    """
    Unique identifier for the project that the dataset belongs under
    """

    dataset_id: str = pydantic.Field()
    """
    Unique identifier for the dataset
    """

    input: typing.Optional[typing.Any] = pydantic.Field(default=None)
    """
    The argument that uniquely define an input case (an arbitrary, JSON serializable object)
    """

    expected: typing.Optional[typing.Any] = pydantic.Field(default=None)
    """
    The output of your application, including post-processing (an arbitrary, JSON serializable object)
    """

    metadata: typing.Optional[DatasetEventMetadata] = pydantic.Field(default=None)
    """
    A dictionary with additional data about the test example, model outputs, or just about anything else that's relevant, that you can use to help find and analyze examples later. For example, you could log the `prompt`, example's `id`, or anything else that would be useful to slice/dice later. The values in `metadata` can be any JSON-serializable type, but its keys must be strings
    """

    tags: typing.Optional[typing.List[str]] = pydantic.Field(default=None)
    """
    A list of tags to log
    """

    span_id: str = pydantic.Field()
    """
    A unique identifier used to link different dataset events together as part of a full trace. See the [tracing guide](https://www.braintrust.dev/docs/instrument) for full details on tracing
    """

    root_span_id: str = pydantic.Field()
    """
    A unique identifier for the trace this dataset event belongs to
    """

    is_root: typing.Optional[bool] = pydantic.Field(default=None)
    """
    Whether this span is a root span
    """

    origin: typing.Optional[ObjectReferenceNullish] = None
    comments: typing.Optional[typing.List[typing.Optional[typing.Any]]] = pydantic.Field(default=None)
    """
    Optional list of comments attached to this event
    """

    audit_data: typing.Optional[typing.List[typing.Optional[typing.Any]]] = pydantic.Field(default=None)
    """
    Optional list of audit entries attached to this event
    """

    facets: typing.Optional[typing.Dict[str, typing.Any]] = pydantic.Field(default=None)
    """
    Facets for categorization (dictionary from facet id to value)
    """

    classifications: typing.Optional[
        typing.Dict[str, typing.Optional[typing.List[DatasetEventClassificationsValueItem]]]
    ] = pydantic.Field(default=None)
    """
    Classifications for this event (dictionary from classification name to items)
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
